#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
long long p2=0,p1=0;
for(int i=2;i<=n;++i){long long cur=min(p1+a[i-1],p2+a[i-2]);p2=p1;p1=cur;}
printf("%lld\n",p1);return 0;}

